@js:
var result = [];
var baseUrl = "/api/cate";

// 动态获取标签
var tags = [];
var doc = org.jsoup.Jsoup.parse(java.ajax(source.key + '/cate'));
var tagContainers = doc.select('.tag-container').toArray();
var lastContainer = tagContainers[tagContainers.length - 1];
var tagElements = lastContainer.select('a');

// 提取标签数据
for (var i = 0; i < tagElements.size(); i++) {
    var element = tagElements.get(i);
    tags.push({
        value: element.attr('data-value'),
        text: element.text()
    });
}

// 排序选项
const sortOptions = [
    { text: "更新", value: 0 },
    { text: "新作", value: 1 },
    { text: "热门", value: 3 },
    { text: "畅销", value: 2 },
    { text: "收藏", value: 4 }
];

// 创建分类项
var createCategory = (title, tag, sort) => {
    const body = {
        page: { page: "{{page}}", pageSize: 36 },
        category: "comic",
        sort: sort,
        comic: { status: -1, day: 0, tag: tag },
        video: { year: 0, typeId: 0, typeId1: 0, area: "", lang: "", status: -1, day: 0 },
        novel: { status: -1, day: 0, sortId: 0 }
    };

    // 构建URL，包含标签值
    const url = baseUrl + (tag ? "/" + tag : "") + "," + JSON.stringify({
        body: JSON.stringify(body).replace('"{{page}}"', '{{page}}'),
        method: "POST",
        headers: {
            "X-Requested-With": "XMLHttpRequest",
            "Content-Type": "application/json",
            "authHeader": source.getLoginHeader() || ""
        }
    });

    result.push({
        title: title,
        url: url,
        style: {
            layout_flexGrow: 1,
            layout_flexBasisPercent: 0.25
        }
    });
};

// 生成分类
sortOptions.forEach(so => {
    // 添加排序标题
    result.push({
        title: so.text,
        url: "",
        style: { 
            layout_flexGrow: 1, 
            layout_flexBasisPercent: 1 
        }
    });

    // 添加该排序下的所有标签
    tags.forEach(tag => {
        createCategory(tag.text, tag.value, so.value);
    });
});

JSON.stringify(result);

